<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #f4f6f9; color: #222; line-height: 1.5; padding: 20px; max-width: 800px; margin: 0 auto; }
  h1 { text-align: center; margin-bottom: 24px; font-size: 1.6rem; }

  /* Form */
  .form-section { background: #fff; border-radius: 8px; padding: 20px; margin-bottom: 20px; box-shadow: 0 1px 3px rgba(0,0,0,.1); }
  .form-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: flex-end; margin-bottom: 10px; }
  .form-group { display: flex; flex-direction: column; flex: 1; min-width: 120px; }
  .form-group label { font-size: 0.85rem; font-weight: 600; margin-bottom: 3px; color: #444; }
  input, select { padding: 8px 10px; border: 1px solid #ccc; border-radius: 5px; font-size: 0.95rem; background: #fff; }
  input:focus, select:focus { outline: none; border-color: #4a7cff; box-shadow: 0 0 0 2px rgba(74,124,255,.18); }
  button#add-expense { padding: 9px 20px; background: #4a7cff; color: #fff; border: none; border-radius: 5px; font-size: 0.95rem; cursor: pointer; font-weight: 600; align-self: flex-end; }
  button#add-expense:hover { background: #3662d4; }

  .error-msg { color: #c0392b; font-size: 0.88rem; min-height: 1.2em; margin-top: 4px; padding: 0 5px; }

  /* Filters */
  .filters-section { background: #fff; border-radius: 8px; padding: 16px 20px; margin-bottom: 20px; box-shadow: 0 1px 3px rgba(0,0,0,.1); display: flex; gap: 14px; flex-wrap: wrap; align-items: flex-end; }
  .filters-section .form-group { min-width: 100px; }

  /* Summary */
  .summary-bar { background: #fff; border-radius: 8px; padding: 16px 20px; margin-bottom: 20px; box-shadow: 0 1px 3px rgba(0,0,0,.1); display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
  .summary-bar .total-label { font-weight: 600; color: #444; }
  #total { font-size: 1.3rem; font-weight: 700; color: #2c3e50; }
  .cat-sums { display: flex; gap: 18px; flex-wrap: wrap; }
  .cat-total { background: #f0f4ff; padding: 4px 12px; border-radius: 5px; font-size: 0.9rem; color: #3662d4; font-weight: 600; }

  /* Expense list */
  .list-section { background: #fff; border-radius: 8px; padding: 16px 20px; box-shadow: 0 1px 3px rgba(0,0,0,.1); }
  .list-section h2 { font-size: 1.1rem; margin-bottom: 12px; color: #444; }
  table.expenses-table { width: 100%; border-collapse: collapse; }
  table.expenses-table th { text-align: left; padding: 8px 6px; font-size: 0.8rem; color: #777; border-bottom: 2px solid #eee; text-transform: uppercase; letter-spacing: .5px; }
  table.expenses-table td { padding: 10px 6px; border-bottom: 1px solid #f0f0f0; font-size: 0.93rem; vertical-align: middle; }
  tr.expense.hidden { display: none; }
  .exp-amount { font-weight: 700; color: #2c3e50; white-space: nowrap; }
  .exp-cat { text-transform: capitalize; }
  .exp-date { color: #666; white-space: nowrap; }
  .exp-note { color: #888; font-style: italic; max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .exp-del { background: none; border: 1px solid #e74c3c; color: #e74c3c; padding: 3px 10px; border-radius: 4px; cursor: pointer; font-size: 0.82rem; transition: background .15s, color .15s; }
  .exp-del:hover { background: #e74c3c; color: #fff; }

  .empty-msg { text-align: center; padding: 30px 10px; color: #aaa; font-size: 0.95rem; }

  @media (max-width: 600px) {
    .form-row, .filters-section { flex-direction: column; }
    .form-group { min-width: 100%; }
    button#add-expense { width: 100%; text-align: center; }
  }
</style>
</head>
<body>

<h1>💰 Expense Tracker</h1>

<!-- Entry Form -->
<div class="form-section">
  <div class="form-row">
    <div class="form-group" style="max-width:160px;">
      <label for="amount">Amount ($)</label>
      <input type="number" id="amount" placeholder="0.00" step="0.01" min="0">
    </div>
    <div class="form-group" style="max-width:180px;">
      <label for="category">Category</label>
      <select id="category">
        <option value="">— select —</option>
        <option value="groceries">groceries</option>
        <option value="transport">transport</option>
        <option value="bills">bills</option>
        <option value="fun">fun</option>
      </select>
    </div>
    <div class="form-group" style="max-width:180px;">
      <label for="date">Date</label>
      <input type="date" id="date">
    </div>
  </div>
  <div class="form-row">
    <div class="form-group">
      <label for="note">Note (optional)</label>
      <input type="text" id="note" placeholder="e.g. Weekly shopping">
    </div>
    <button id="add-expense">Add Expense</button>
  </div>
  <div class="error-msg" id="form-error"></div>
</div>

<!-- Filters -->
<div class="filters-section">
  <div class="form-group" style="max-width:180px;">
    <label for="filter-category">Filter Category</label>
    <select id="filter-category">
      <option value="all">all</option>
      <option value="groceries">groceries</option>
      <option value="transport">transport</option>
      <option value="bills">bills</option>
      <option value="fun">fun</option>
    </select>
  </div>
  <div class="form-group" style="max-width:170px;">
    <label for="filter-from">From Date</label>
    <input type="date" id="filter-from">
  </div>
  <div class="form-group" style="max-width:170px;">
    <label for="filter-to">To Date</label>
    <input type="date" id="filter-to">
  </div>
</div>

<!-- Summary -->
<div class="summary-bar">
  <span><span class="total-label">Visible Total:</span> <span id="total">0.00</span></span>
  <div class="cat-sums" id="cat-sums"></div>
</div>

<!-- Expense List -->
<div class="list-section">
  <h2>Expenses</h2>
  <table class="expenses-table">
    <thead>
      <tr><th>Amount</th><th>Category</th><th>Date</th><th>Note</th><th></th></tr>
    </thead>
    <tbody id="expense-tbody"></tbody>
  </table>
  <div class="empty-msg" id="empty-msg">No expenses yet. Add one above!</div>
</div>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "expense_tracker_data";
  var categories = ["groceries", "transport", "bills", "fun"];

  // --- State ---
  var expenses = [];

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        expenses = JSON.parse(raw);
      }
    } catch (_) {
      expenses = [];
    }
  }

  function saveExpenses() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
  }

  // --- DOM refs ---
  var amountInput   = document.getElementById("amount");
  var categorySelect = document.getElementById("category");
  var dateInput     = document.getElementById("date");
  var noteInput     = document.getElementById("note");
  var addBtn        = document.getElementById("add-expense");
  var formError     = document.getElementById("form-error");

  var filterCat    = document.getElementById("filter-category");
  var filterFrom   = document.getElementById("filter-from");
  var filterTo     = document.getElementById("filter-to");

  var totalEl      = document.getElementById("total");
  var catSumsEl    = document.getElementById("cat-sums");
  var tbody        = document.getElementById("expense-tbody");
  var emptyMsg     = document.getElementById("empty-msg");

  // Set default date to today
  dateInput.value = new Date().toISOString().slice(0, 10);

  // --- Validation & Add ---
  function setFormError(msg) {
    formError.textContent = msg;
  }

  function clearFormError() {
    formError.textContent = "";
  }

  addBtn.addEventListener("click", function () {
    clearFormError();

    var amountVal = amountInput.value.trim();
    var catVal    = categorySelect.value.trim();
    var dateVal   = dateInput.value.trim();
    var noteVal   = noteInput.value.trim();

    // Validate amount: must be present, numeric, > 0
    if (amountVal === "" || isNaN(Number(amountVal)) || Number(amountVal) <= 0) {
      setFormError("Please enter a valid positive amount.");
      return;
    }

    // Validate date
    if (dateVal === "") {
      setFormError("Please select a date.");
      return;
    }

    var expense = {
      id: Date.now() + Math.floor(Math.random() * 1000),
      amount: parseFloat(Number(amountVal).toFixed(2)),
      category: catVal || "groceries",
      date: dateVal,
      note: noteVal,
      createdAt: new Date().toISOString()
    };

    expenses.push(expense);
    saveExpenses();

    // Clear amount field and reset form slightly
    amountInput.value = "";
    noteInput.value = "";
    categorySelect.value = "";
    dateInput.value = new Date().toISOString().slice(0, 10);
    amountInput.focus();

    renderAll();
  });

  // --- Delete (event delegation) ---
  tbody.addEventListener("click", function (e) {
    var delBtn = e.target.closest(".exp-del");
    if (!delBtn) return;
    var id = Number(delBtn.getAttribute("data-id"));
    expenses = expenses.filter(function (ex) { return ex.id !== id; });
    saveExpenses();
    renderAll();
  });

  // --- Filters ---
  filterCat.addEventListener("change", renderAll);
  filterFrom.addEventListener("input", renderAll);
  filterTo.addEventListener("input", renderAll);

  // --- Render ---
  function getVisible() {
    var fCat = filterCat.value;
    var fFrom = filterFrom.value;
    var fTo   = filterTo.value;

    return expenses.filter(function (ex) {
      if (fCat !== "all" && ex.category !== fCat) return false;
      if (fFrom && ex.date < fFrom) return false;
      if (fTo && ex.date > fTo) return false;
      return true;
    });
  }

  function renderAll() {
    var visible = getVisible();

    // Total
    var totalSum = visible.reduce(function (s, e) { return s + e.amount; }, 0);
    totalEl.textContent = totalSum.toFixed(2);

    // Per-category summaries (visible only)
    catSumsEl.innerHTML = "";
    categories.forEach(function (cat) {
      var sum = visible.filter(function (e) { return e.category === cat; })
                       .reduce(function (s, e) { return s + e.amount; }, 0);
      if (sum > 0 || true) { // show all even if zero for clarity
        var span = document.createElement("span");
        span.className = "cat-total";
        span.setAttribute("data-cat", cat);
        span.textContent = cat + ": " + sum.toFixed(2);
        catSumsEl.appendChild(span);
      }
    });

    // Sort expenses newest first (by createdAt desc, then by id desc as fallback)
    var sorted = expenses.slice().sort(function (a, b) {
      return new Date(b.createdAt) - new Date(a.createdAt);
    });

    tbody.innerHTML = "";
    if (sorted.length === 0) {
      emptyMsg.style.display = "block";
    } else {
      emptyMsg.style.display = "none";
      sorted.forEach(function (ex) {
        var tr = document.createElement("tr");
        tr.className = "expense";

        // Check if this expense is visible
        var isVisible = true;
        if (filterCat.value !== "all" && ex.category !== filterCat.value) isVisible = false;
        if (filterFrom.value && ex.date < filterFrom.value) isVisible = false;
        if (filterTo.value && ex.date > filterTo.value) isVisible = false;

        if (!isVisible) tr.classList.add("hidden");

        var tdAmount  = document.createElement("td");
        tdAmount.className = "exp-amount";
        tdAmount.textContent = "$" + ex.amount.toFixed(2);

        var tdCat = document.createElement("td");
        tdCat.className = "exp-cat";
        tdCat.textContent = ex.category;

        var tdDate = document.createElement("td");
        tdDate.className = "exp-date";
        tdDate.textContent = ex.date;

        var tdNote = document.createElement("td");
        tdNote.className = "exp-note";
        tdNote.textContent = ex.note || "";
        if (!ex.note) tdNote.style.color = "#ccc";

        var tdDel = document.createElement("td");
        var delBtn = document.createElement("button");
        delBtn.className = "exp-del";
        delBtn.setAttribute("data-id", ex.id);
        delBtn.textContent = "Delete";
        tdDel.appendChild(delBtn);

        tr.appendChild(tdAmount);
        tr.appendChild(tdCat);
        tr.appendChild(tdDate);
        tr.appendChild(tdNote);
        tr.appendChild(tdDel);
        tbody.appendChild(tr);
      });
    }
  }

  // --- Init ---
  loadExpenses();
  renderAll();

})();
</script>

</body>
</html>
